export class CustodyListPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);
  private auth = inject(AuthService);
  protected router = inject(Router);
  private api = inject(ApiClient);
  private translate = inject(TranslateService);
  private moneyPipe = new MoneyPipe();
  private datePipe = new DatetimePipe();

  // ── N-03: the quick view ──────────────────────────────────────────────────

  private readonly quickView = viewChild.required(QuickViewComponent);
  /** the list row the quick view was opened from — its status and id decide the drawer's actions */
  protected readonly quickRow = signal<Row | null>(null);
  readonly quick = signal<CustodyQuick | null>(null);
  readonly quickLoading = signal(false);
  readonly quickReturnFocus = signal<HTMLElement | null>(null);

  readonly quickRoute = computed<readonly unknown[]>(() => {
    const row = this.quickRow();
    return row === null ? [] : ['/custodies', row.id];
  });

  /** who holds it, and its number — under the drawer's title */
  readonly quickSubtitle = computed(() => {
    const row = this.quickRow();
    return row === null ? '' : `#${row.id} · ${row.agent ?? '—'}`;
  });

  /** N-03: a row was activated — its summary opens in the drawer; the list, its filters and the address stay */
  openQuickView(row: unknown, element: HTMLElement | null): void {
    const record = row as Row;
    // a double click is one drawer
    if (this.quickLoading() || this.quickView().visible()) {
      return;
    }
    this.quickRow.set(record);
    this.quickReturnFocus.set(element);
    this.quick.set(null);
    this.quickLoading.set(true);
    this.quickView().open();
    void firstValueFrom(this.http.get<ItemResponse<CustodyQuick>>(`/custodies/${record.id}`))
      .then((res) => {
        this.quickLoading.set(false);
        this.quick.set(res.data);
      })
      .catch((err: unknown) => {
        this.quickLoading.set(false);
        this.quickView().close();
        const failure = (err as HttpErrorResponse).error as { message?: string; code?: string } | null;
        this.toast.apiError(failure?.message ?? 'errors.generic', failure?.code);
      });
  }

  /** the summary: the money first */
  quickItems(c: CustodyQuick): KeyValueItem[] {
    return [
      { label: 'custody.list.col_amount', value: this.moneyPipe.transform(c.amount, false) },
      { label: 'custody.list.col_spent', value: this.moneyPipe.transform(c.spent, false) },
      { label: 'custody.list.col_returned', value: this.moneyPipe.transform(c.returned, false) },
      { label: 'dashboard.agent.frozen', value: this.moneyPipe.transform(c.frozen, false) },
      { label: 'custody.list.col_remaining', value: this.moneyPipe.transform(c.remaining, false) },
      { label: 'glossary.treasury', value: c.treasury ?? '—' },
      { label: 'glossary.accountant', value: c.accountant ?? '—' },
      { label: 'common.date', value: this.datePipe.transform(c.created_at, false) },
      ...(c.notes ? [{ label: 'common.notes', value: c.notes }] : []),
    ];
  }

  /** the drawer's reject is the list's own: the reason dialog, about this custody's money */
  rejectFromQuick(): void {
    const row = this.quickRow();
    if (row === null) {
      return;
    }
    this.quickView().close(false);
    this.openReject(row);
  }

  constructor() {
    void firstValueFrom(this.api.loadLookups()).then((l) => {
      this.agentOptions.set(l.agents);
    });
  }

  readonly tableKey = 'list.component';

  readonly columns = [
    { field: 'agent', searchField: 'agent', header: 'custody.list.col_agent', sortable: true },
    { field: 'amount', header: 'custody.list.col_amount', sortable: true, numeric: true },
    { field: 'transferred_in', header: 'custody.list.col_transferred_in', sortable: true, numeric: true },
    { field: 'transferred_out', header: 'custody.list.col_transferred_out', sortable: true, numeric: true },
    { field: 'spent', header: 'custody.list.col_spent', sortable: true, numeric: true },
    { field: 'remaining', header: 'custody.list.col_remaining', sortable: true, numeric: true },
    { field: 'spent_percent', header: 'custody.list.col_spent_percent', sortable: true, numeric: true },
    { field: 'status', header: 'custody.list.col_status', sortable: true },
    { field: 'actions', header: 'common.actions', sortable: false },
  ];

  /** status choices — the exact values CustodyController@index filters on */
  readonly statusTabs = [
    { value: 'all' },
    { value: 'pending' },
    { value: 'accepted' },
    { value: 'active' },
    { value: 'partially_returned' },
    { value: 'closed' },
    { value: 'cancelled' },
    { value: 'rejected' },
  ];

  /** status select options with translated labels (Arabic-only UI) */
  readonly statusOptions = computed(() =>
    this.statusTabs.map((t) => ({
      value: t.value,
      label:
        t.value === 'all'
          ? this.translate.instant('custody.list.tab_all')
          : this.translate.instant(`enums.custody_status.${t.value}`),
    })),
  );

  /** agent filter choices from the shared lookups */
  readonly agentOptions = signal<{ id: number; name: string }[]>([]);

  /** Blade actions.blade.php shows the return modal for the agent's own accepted custody */
  readonly openStates = ['accepted', 'active', 'partially_returned'];


  /** the export replays EXACTLY the params this list was fetched with
   *  (minus paging) — the file always matches the table on screen */
  tableExportQuery(): Record<string, string> {
    const query = cleanParams(this.params());
    delete query.page;
    delete query.per_page;
    return query;
  }

  params = signal<CustodyListParams>({ page: 1, per_page: 25, q: '', status: 'all' });

  data = resource<ListResponse<Row>, unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<Row>>('/custodies', { params: cleanParams(this.params()) })),
  });

  canCreate = computed(() => this.auth.can('may_create_custody'));
  canApprove = computed(() => this.auth.can('may_approve_custody'));
  isAgent = computed(() => this.auth.can('is_agent'));
  /** Blade: accountants and managers get the office variants of the create buttons */
  isOffice = computed(() => this.auth.can('is_accountant') || this.auth.can('is_manager'));

  /** creation variants in the split button (T6-10): for me / as agent / transfer */
  createMenuItems = computed<MenuItem[]>(() => [
    { label: this.translate.instant('custody.list.personal_request'), command: () => void this.router.navigateByUrl('/custodies/new?for=self') },
    { label: this.translate.instant('custody.list.agent_request'), command: () => void this.router.navigateByUrl('/custodies/new') },
    { label: this.translate.instant('custody.list.transfer_custody'), command: () => void this.router.navigateByUrl('/transfers/new') },
  ]);

  /** B-13/D-03: the quiet "⋯" menu — tracking + my custodies leave the header row */
  readonly moreMenuItems = computed<MenuItem[]>(() => [
    { label: this.translate.instant('nav.custody_tracking'), command: () => void this.router.navigateByUrl('/custodies/tracking') },
    { label: this.translate.instant('nav.my_custodies'), command: () => void this.router.navigateByUrl('/custodies/mine') },
  ]);

  /** N-08: where the empty state's call to action goes — the same page as the header's create button */
  readonly firstCustodyRoute: readonly unknown[] = ['/custodies', 'new'];

  /** N-08: the status chips filter outside the table — the table must know, to say "no results" and not "no data" */
  pageFiltered = (): boolean => this.params().status !== 'all';

  /** N-08: the table's "clear the filters" clears the chips too */
  clearPageFilters(): void {
    if (this.params().status === 'all') {
      return;
    }
    this.params.update((p) => ({ ...p, status: 'all', page: 1 }));
    reloadList(this.data);
  }

  /** P-02: the status quick-filter chips — live counts from meta.summary */
  readonly statusChips: { value: string; label: string; countKey: string }[] = [
    { value: 'all', label: 'custody.list.tab_all', countKey: 'total' },
    { value: 'pending', label: 'enums.custody_status.pending', countKey: 'pending' },
    { value: 'accepted', label: 'enums.custody_status.accepted', countKey: 'accepted' },
    { value: 'active', label: 'enums.custody_status.active', countKey: 'active' },
    { value: 'rejected', label: 'enums.custody_status.rejected', countKey: 'rejected' },
    { value: 'closed', label: 'custody.list.closed_or_cancelled', countKey: 'closed_or_cancelled' },
  ];

  // ── T6-30: table-driven filter definitions (agent, status) ────────────
  readonly filterDefs = computed<TableFilterDef[]>(() => [
    {
      key: 'status', label: 'common.status', type: 'select', order: 1,
      options: this.statusOptions().filter((o) => o.value !== 'all'),
    },
    {
      key: 'agent_id', label: 'custody.list.col_agent', type: 'select', order: 2,
      options: this.agentOptions().map((a) => ({ value: a.id, label: a.name })),
    },
  ]);

  /** the table emits the full query — filters reach the server (T6-30) */
  onQuery(query: TableQuery): void {
    const f = query.filters;
    this.params.update((p) => ({
      ...p,
      page: query.page,
      per_page: query.perPage,
      sort: query.sort !== '' ? query.sort : p.sort,
      q: query.q,
      status: (f.status as string) ?? 'all',
      agent_id: (f.agent_id as number) ?? null,
    }));
    reloadList(this.data);
  }

  active = signal<Row | null>(null);
  sending = signal(false);
  actionError = signal<HttpErrorResponse | null>(null);

  private reason = viewChild.required(ReasonDialogComponent);

  summaryValue(key: string): string {
    const value = this.data.value()?.meta.summary?.[key];
    return typeof value === 'number' || typeof value === 'string' ? String(value) : '0';
  }

  setParam(key: string, value: string | number | null): void {
    this.params.update((p) => ({ ...p, [key]: value, page: 1 }));
    reloadList(this.data);
  }

  onSearch(term: string): void { this.setParam('q', term); }

  /** row actions per status/role (actions.blade.php) — view/accept/return link to the detail, reject opens the reason dialog */
  actionsFor(row: Row): RowActionItem[] {
    return [
      { icon: 'eye', label: 'common.view', severity: 'info', route: ['/custodies', row.id] },
      {
        icon: 'check',
        label: 'custody.detail.accept',
        route: ['/custodies', row.id],
        visible: row.status === 'pending' && this.canApprove(),
      },
      {
        icon: 'x',
        label: 'custody.list.reject_action',
        severity: 'danger',
        handler: () => { this.openReject(row); },
        visible: row.status === 'pending' && this.canApprove(),
      },
      {
        icon: 'cash',
        label: 'custody.detail.return',
        route: ['/custodies', row.id],
        visible: this.isAgent() && this.openStates.includes(row.status),
      },
    ];
  }

  openReject(row: Row): void {
    this.active.set(row);
    this.actionError.set(null);
    this.reason().open();
  }

  /** N-06: what the reject confirm is about — the custody's amount and who holds it */
  readonly rejectDetails = computed<readonly KeyValueItem[]>(() => {
    const row = this.active();
    if (row === null) {
      return [];
    }
    return [
      { label: 'common.amount_egp', value: this.moneyPipe.transform(row.amount, false) },
      { label: 'custody.list.col_agent', value: row.agent ?? '—' },
    ];
  });

  submitReject(reason: string): void {
    if (this.sending()) {
      return;
    }
    const row = this.active();
    if (row === null) {
      return;
    }
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(this.http.post<ActionResponse>(`/custodies/${row.id}/reject`, { reason }))
      .then((res) => {
        this.sending.set(false);
        this.reason().done();
        this.toast.success(res.message);
        reloadList(this.data);
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        const response = err instanceof HttpErrorResponse ? err : null;
        this.actionError.set(response);
        if (response) {
          this.toast.apiError(response.error?.message ?? 'errors.generic', response.error?.code);
        }
      });
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
    const current = this.params();
    const sort = event.sort ?? '';
    if (current.page === event.page && current.per_page === event.per_page && current.sort === sort) {
      return;
    }
    this.params.update((p) => ({ ...p, page: event.page, per_page: event.per_page, sort }));
    reloadList(this.data);
  }
}

function cleanParams(params: object): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && value !== '' && value !== 'all') {
      result[key] = String(value);
    }
  }
  return result;
}
